import{_ as i,l as o,o as e,c as l,v as t,p as n,x as r,d as h,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Dijkstra THE 多层","description":"","frontmatter":{"title":"Dijkstra THE 多层","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dijkstra-the.md","filePath":"cs/dijkstra-the.md","lastUpdated":1789023840000}'),c={name:"cs/dijkstra-the.md"};function p(m,a,T,_,u,A){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="dijkstra-the-多层" tabindex="-1">Dijkstra THE 多层 <a class="header-anchor" href="#dijkstra-the-多层" aria-label="Permalink to &quot;Dijkstra THE 多层&quot;">​</a></h1><div class="epigraph"><p>把多道程序系统收成严格分层：每层只使用下层已经证明的抽象，处理器、存储器与用户进程各有一层。</p><footer>—— Dijkstra, The Structure of the THE Multiprogramming System, CACM 1968</footer></div><p><a href="/cs/dijkstra-mutex">上一课</a>附录对照了 1965 年临界区短文。附录对照，不插入主干。主干已在<a href="/cs/kernel-user">内核与用户态</a>、<a href="/cs/process-image">进程映像</a>、<a href="/cs/semaphore">信号量</a>里用过分层抽象与 P/V；这里对照 <strong>THE 系统原文的问题</strong>：如何把一台多道机器建成可推理的层，而不是一堆互相调用的例程。不重做 CFS，也不把本篇插回进程课之前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1965 文给出互斥规格，不管整机结构。THE 的缺口是系统：层 0 处理中断与处理器分配，之上存储、通信、I/O、用户程序，每层只看见下层的接口。信号量在文中作为层间同步。主干 OS 课按映像、调度、虚存、文件走，并不采用 THE 的层号当课序。附录只对照「分层使正确性可逐层谈」。</p><p><span class="marginnote">THE 是 Eindhoven 的系统名（Technische Hogeschool Eindhoven），不是英语定冠词游戏。层次与后来微内核不是同一场辩论；Tanenbaum 对照更后。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自底向上：先保证中断与时钟，再保证段与进程不会破坏下层不变量。测试与「层次证明」的叙事是原文风格：先让下层无错，上层才能当它为公理。主干<a href="/cs/privilege-rings">特权级</a>用硬件级实现类似的不可逾越；THE 更多是软件结构。</p>',8)),(e(),n(E,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22%E5%B1%82%3A%20%E5%A4%84%E7%90%86%E5%99%A8%E4%B8%8E%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20L1%5B%22%E5%AD%98%E5%82%A8%E4%B8%8E%E8%BF%9B%E7%A8%8B%E6%8A%BD%E8%B1%A1%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E9%80%9A%E4%BF%A1%E4%B8%8E%20I%2FO%22%5D%0A%20%20L2%20--%3E%20USER%5B%22%E7%94%A8%E6%88%B7%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20L0%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%86%85%E6%A0%B8%E8%BE%B9%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层把<a href="/cs/toctou">完整中介</a> 做成结构：上层无法直接踩时钟与中断屏蔽。信号量把 1965 的临界区收成可组合原语，主干信号量课已取用。THE 不管关系模型、不管 TCP。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 1968 插在互斥规格之后当「下一课 OS」，读者会按 THE 层号上课，而本栏 OS 第一课接运行时与进程映像。附录只对照分层作为可发表的系统结构，下一篇才把「先于」收到无共享内存的消息上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 THE 与 1965 短文混成一篇——上一附录已警告。也不要在此展开微内核消息。下一篇对照 Lamport 1978 逻辑时钟。</p><p>对照结束应回到主干<a href="/cs/process-image">进程映像</a>与<a href="/cs/semaphore">信号量</a>。THE 层号不插入课序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Dijkstra 1968 THE：多道系统的严格分层。</li><li>主干内核与信号量课已取用抽象；本篇不插入进程课之前。</li><li>出处：Dijkstra, <em>CACM</em> 1968。</li></ul>',9))])}const k=i(c,[["render",p]]);export{f as __pageData,k as default};
